"""Merge user records from JSON, CSV and Parquet sources by priority."""
import json
from pathlib import Path

import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

SOURCES = [
    ("source_a", "/data/source_a/users.json"),
    ("source_b", "/data/source_b/users.csv"),
    ("source_c", "/data/source_c/users.parquet"),
]

# canonical field -> accepted raw names
FIELD_MAP = {
    "user_id": {"user_id", "id", "userId"},
    "email": {"email", "email_address"},
    "name": {"full_name", "name", "userName"},
    "created_date": {"registration_date", "created_at", "joined"},
    "status": {"status", "is_active", "active"},
}
FIELDS = ["name", "email", "created_date", "status"]
OUTPUT_COLUMNS = ["user_id", "name", "email", "created_date", "status"]


def read_source(path: str) -> pd.DataFrame:
    p = Path(path)
    if p.suffix == ".json":
        with p.open() as f:
            return pd.json_normalize(json.load(f))
    if p.suffix == ".csv":
        return pd.read_csv(p)
    if p.suffix == ".parquet":
        return pq.read_table(p).to_pandas()
    raise ValueError(f"unsupported source: {path}")


def rename_fields(df: pd.DataFrame) -> pd.DataFrame:
    mapping = {}
    for col in df.columns:
        for canonical, aliases in FIELD_MAP.items():
            if col in aliases:
                mapping[col] = canonical
                break
    return df.rename(columns=mapping)


def normalize_date(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    text = str(value).strip()
    if not text:
        return None
    return pd.to_datetime(text, errors="coerce").strftime("%Y-%m-%d")


def normalize_status(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    if isinstance(value, bool) or str(value).strip().lower() in {"true", "false"}:
        truthy = value if isinstance(value, bool) else str(value).strip().lower() == "true"
        return "active" if truthy else "inactive"
    text = str(value).strip()
    return text or None


def normalize_text(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    text = str(value).strip()
    return text or None


def normalize_user_id(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    return int(str(value).strip())


def main():
    frames = []
    by_source = {}
    for source, path in SOURCES:
        df = rename_fields(read_source(path))
        if "user_id" not in df.columns:
            raise ValueError(f"{source} has no user_id column")
        for field in FIELDS:
            if field not in df.columns:
                df[field] = None

        records = {}
        for row in df.to_dict("records"):
            uid = normalize_user_id(row.get("user_id"))
            if uid is None:
                continue
            records[uid] = {
                "user_id": uid,
                "name": normalize_text(row.get("name")),
                "email": normalize_text(row.get("email")),
                "created_date": normalize_date(row.get("created_date")),
                "status": normalize_status(row.get("status")),
            }
        by_source[source] = records
        frames.append(pd.DataFrame(records.values(), columns=OUTPUT_COLUMNS))

    # Union of all user ids, preserving deterministic ordering.
    user_ids = sorted({uid for records in by_source.values() for uid in records})

    merged_rows = []
    conflicts = []
    for uid in user_ids:
        row = {"user_id": uid}
        for field in FIELDS:
            present = {
                source: records[uid][field]
                for source, records in by_source.items()
                if uid in records and records[uid][field] is not None
            }
            if not present:
                row[field] = None
                continue
            distinct = list(dict.fromkeys(present.values()))
            if len(distinct) > 1:
                selected = next(
                    present[source] for source, _ in SOURCES if source in present
                )
                conflicts.append(
                    {
                        "user_id": uid,
                        "field": field,
                        "values": {
                            source: present[source]
                            for source, _ in SOURCES
                            if source in present
                        },
                        "selected": selected,
                    }
                )
            row[field] = next(
                present[source] for source, _ in SOURCES if source in present
            )
        merged_rows.append(row)

    merged = pd.DataFrame(merged_rows, columns=OUTPUT_COLUMNS)
    merged["user_id"] = merged["user_id"].astype("int64")
    for field in ["name", "email", "created_date", "status"]:
        merged[field] = merged[field].astype("string")

    table = pa.Table.from_pandas(merged, preserve_index=False)
    expected = pa.schema(
        [
            pa.field("user_id", pa.int64()),
            pa.field("name", pa.string()),
            pa.field("email", pa.string()),
            pa.field("created_date", pa.string()),
            pa.field("status", pa.string()),
        ]
    )
    table = table.cast(expected)
    pq.write_table(table, "/app/merged_users.parquet")

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as f:
        json.dump(report, f, indent=2)
        f.write("\n")

    print(f"merged {len(merged)} users, {len(conflicts)} conflicts")


if __name__ == "__main__":
    main()

